1946: 		private sealed class ArrayMultiSortMethod : FunctionMethod
1947: 		{
1948: 			public ArrayMultiSortMethod()
1949: 			{
1950: 				ReturnType = typeof(Int64);
1951: 				argumentTypeArray = null;
1952: 				CanRestructure = false;
1953: 				HasUniqueRestructure = true;
1954: 			}
1955: 			public override string CheckArgumentType(string name, IOperandTerm[] arguments)
1956: 			{
1957: 				if (arguments.Length < 2)
1958: 					return string.Format("{0}関数:少なくとも{1}の引数が必要です", name, 2);
1959: 				for (int i = 0; i < arguments.Length; i++)
1960: 				{
1961: 					if (arguments[i] == null)
1962: 						return string.Format("{0}関数:{1}番目の引数は省略できません", name, i + 1);
1963:                     if (!(arguments[i] is VariableTerm varTerm) || varTerm.Identifier.IsCalc || varTerm.Identifier.IsConst)
1964:                         return string.Format("{0}関数:{1}番目の引数が変数ではありません", name, i + 1);
1965:                     if (varTerm.Identifier.IsCharacterData)
1966: 						return string.Format("{0}関数:{1}番目の引数がキャラクタ変数です", name, i + 1);
1967: 					if (i == 0 && !varTerm.Identifier.IsArray1D)
1968: 						return string.Format("{0}関数:{1}番目の引数が一次元配列ではありません", name, i + 1);
1969: 					if (!varTerm.Identifier.IsArray1D && !varTerm.Identifier.IsArray2D && !varTerm.Identifier.IsArray2D)
1970: 						return string.Format("{0}関数:{1}番目の引数が配列変数ではありません", name, i + 1);
1971: 				}
1972: 				return null;
1973: 			}
1974: 			public override Int64 GetIntValue(ExpressionMediator exm, IOperandTerm[] arguments)
1975: 			{
1976: 				VariableTerm varTerm = arguments[0] as VariableTerm;
1977: 				int[] sortedArray;
1978: 				if (varTerm.Identifier.IsInteger)
1979: 				{
1980: 					List<KeyValuePair<Int64, int>> sortList = new List<KeyValuePair<long, int>>();
1981: 					Int64[] array = (Int64[])varTerm.Identifier.GetArray();
1982: 					for (int i = 0; i < array.Length; i++)
1983: 					{
1984: 						if (array[i] == 0)
1985: 							break;
1986: 						if (array[i] < Int64.MinValue || array[i] > Int64.MaxValue)
1987: 							return 0;
1988: 						sortList.Add(new KeyValuePair<long, int>(array[i], i));
1989: 					}
1990:                     //素ではintの範囲しか扱えないので一工夫
1991:                     sortList.Sort((a, b) => { return Math.Sign(a.Key - b.Key); });
1992: 					sortedArray = new int[sortList.Count];
1993: 					for (int i = 0; i < sortedArray.Length; i++)
1994: 						sortedArray[i] = sortList[i].Value;
1995: 				}
1996: 				else
1997: 				{
1998: 					List<KeyValuePair<string, int>> sortList = new List<KeyValuePair<string, int>>();
1999: 					string[] array = (string[])varTerm.Identifier.GetArray();
2000: 					for (int i = 0; i < array.Length; i++)
2001: 					{
2002: 						if (string.IsNullOrEmpty(array[i]))
2003: 							return 0;
2004: 						sortList.Add(new KeyValuePair<string, int>(array[i], i));
2005: 					}
2006: 					sortList.Sort((a, b) => { return a.Key.CompareTo(b.Key); });
2007: 					sortedArray = new int[sortList.Count];
2008: 					for (int i = 0; i < sortedArray.Length; i++)
2009: 						sortedArray[i] = sortList[i].Value;
2010: 				}
2011: 				foreach (VariableTerm term in arguments)//もう少し賢い方法はないものだろうか
2012: 				{
2013: 					if (term.Identifier.IsArray1D)
2014: 					{
2015: 						if (term.IsInteger)
2016: 						{
2017: 							var array = (Int64[])term.Identifier.GetArray();
2018: 							var clone = (Int64[])array.Clone();
2019: 							if (array.Length < sortedArray.Length)
2020: 								return 0;
2021: 							for (int i = 0; i < sortedArray.Length; i++)
2022: 								array[i] = clone[sortedArray[i]];
2023: 						}
2024: 						else
2025: 						{
2026: 							var array = (string[])term.Identifier.GetArray();
2027: 							var clone = (string[])array.Clone();
2028: 							if (array.Length < sortedArray.Length)
2029: 								return 0;
2030: 							for (int i = 0; i < sortedArray.Length; i++)
2031: 								array[i] = clone[sortedArray[i]];
2032: 						}
2033: 					}
2034: 					else if (term.Identifier.IsArray2D)
2035: 					{
2036: 						if (term.IsInteger)
2037: 						{
2038: 							var array = (Int64[,])term.Identifier.GetArray();
2039: 							var clone = (Int64[,])array.Clone();
2040: 							if (array.GetLength(0) < sortedArray.Length)
2041: 								return 0;
2042: 							for (int i = 0; i < sortedArray.Length; i++)
2043: 								for (int x = 0; x < array.GetLength(1); x++)
2044: 									array[i, x] = clone[sortedArray[i], x];
2045: 						}
2046: 						else
2047: 						{
2048: 							var array = (string[,])term.Identifier.GetArray();
2049: 							var clone = (string[,])array.Clone();
2050: 							if (array.GetLength(0) < sortedArray.Length)
2051: 								return 0;
2052: 							for (int i = 0; i < sortedArray.Length; i++)
2053: 								for (int x = 0; x < array.GetLength(1); x++)
2054: 									array[i, x] = clone[sortedArray[i], x];
2055: 						}
2056: 					}
2057: 					else if (term.Identifier.IsArray3D)
2058: 					{
2059: 						if (term.IsInteger)
2060: 						{
2061: 							var array = (Int64[, ,])term.Identifier.GetArray();
2062: 							var clone = (Int64[, ,])array.Clone();
2063: 							if (array.GetLength(0) < sortedArray.Length)
2064: 								return 0;
2065: 							for (int i = 0; i < sortedArray.Length; i++)
2066: 								for (int x = 0; x < array.GetLength(1); x++)
2067: 									for (int y = 0; y < array.GetLength(2); y++)
2068: 										array[i, x, y] = clone[sortedArray[i], x, y];
2069: 						}
2070: 						else
2071: 						{
2072: 							var array = (string[, ,])term.Identifier.GetArray();
2073: 							var clone = (string[, ,])array.Clone();
2074: 							if (array.GetLength(0) < sortedArray.Length)
2075: 								return 0;
2076: 							for (int i = 0; i < sortedArray.Length; i++)
2077: 								for (int x = 0; x < array.GetLength(1); x++)
2078: 									for (int y = 0; y < array.GetLength(2); y++)
2079: 										array[i, x, y] = clone[sortedArray[i], x, y];
2080: 						}
2081: 					}
2082: 					else { throw new ExeEE("異常な配列"); }
2083: 				}
2084: 				return 1;
2085: 			}
2086: 			public override bool UniqueRestructure(ExpressionMediator exm, IOperandTerm[] arguments)
2087: 			{
2088: 				for (int i = 0; i < arguments.Length; i++)
2089: 					arguments[i] = arguments[i].Restructure(exm);
2090: 				return false;
2091: 			}
2092: 		}
2093:         #endregion
