1272:         private sealed class MatchMethod : FunctionMethod
1273:         {
1274:             readonly bool isCharaRange;
1275:             public MatchMethod()
1276:             {
1277:                 ReturnType = typeof(Int64);
1278:                 argumentTypeArray = null;
1279:                 isCharaRange = false;
1280:                 CanRestructure = false;
1281:                 HasUniqueRestructure = true;
1282:             }
1283:             public MatchMethod(bool isChara)
1284:             {
1285:                 ReturnType = typeof(Int64);
1286:                 argumentTypeArray = null;
1287:                 isCharaRange = isChara;
1288:                 CanRestructure = false;
1289:                 HasUniqueRestructure = true;
1290:             }
1291:             public override string CheckArgumentType(string name, IOperandTerm[] arguments)
1292:             {
1293:                 if (arguments.Length < 2)
1294:                     return name + "関数には少なくとも2つの引数が必要です";
1295:                 if (arguments.Length > 4)
1296:                     return name + "関数の引数が多すぎます";
1297:                 if (arguments[0] == null)
1298:                     return name + "関数の1番目の引数は省略できません";
1299:                 if (!(arguments[0] is VariableTerm))
1300:                     return name + "関数の1番目の引数が変数ではありません";
1301:                 VariableTerm varToken = (VariableTerm)arguments[0];
1302:                 if (isCharaRange && !varToken.Identifier.IsCharacterData)
1303:                     return name + "関数の1番目の引数がキャラクタ変数ではありません";
1304:                 if (!isCharaRange && (varToken.Identifier.IsArray2D || varToken.Identifier.IsArray3D))
1305:                     return name + "関数は二重配列・三重配列には対応していません";
1306:                 if (!isCharaRange && !varToken.Identifier.IsArray1D)
1307:                     return name + "関数の1番目の引数が配列変数ではありません";
1308:                 if (arguments[1] == null)
1309:                     return name + "関数の2番目の引数は省略できません";
1310:                 if (arguments[1].GetOperandType() != arguments[0].GetOperandType())
1311:                     return name + "関数の1番目の引数と2番目の引数の型が異なります";
1312:                 if ((arguments.Length >= 3) && (arguments[2] != null) && (arguments[2].GetOperandType() != typeof(Int64)))
1313:                     return name + "関数の3番目の引数の型が正しくありません";
1314:                 if ((arguments.Length >= 4) && (arguments[3] != null) && (arguments[3].GetOperandType() != typeof(Int64)))
1315:                     return name + "関数の4番目の引数の型が正しくありません";
1316:                 return null;
1317:             }
1318: 
1319:             public override Int64 GetIntValue(ExpressionMediator exm, IOperandTerm[] arguments)
1320:             {
1321:                 VariableTerm varTerm = arguments[0] as VariableTerm;
1322:                 Int64 start = (arguments.Length > 2 && arguments[2] != null) ? arguments[2].GetIntValue(exm) : 0;
1323:                 Int64 end = (arguments.Length > 3 && arguments[3] != null) ? arguments[3].GetIntValue(exm) : (isCharaRange ? exm.VEvaluator.CHARANUM : varTerm.GetLength());
1324: 
1325:                 FixedVariableTerm p = varTerm.GetFixedVariableTerm(exm);
1326:                 if (!isCharaRange)
1327:                 {
1328:                     p.IsArrayRangeValid(start, end, "MATCH", 3L, 4L);
1329:                     if (arguments[0].GetOperandType() == typeof(Int64))
1330:                     {
1331:                         Int64 targetValue = arguments[1].GetIntValue(exm);
1332:                         return (exm.VEvaluator.GetMatch(p, targetValue, start, end));
1333:                     }
1334:                     else
1335:                     {
1336:                         string targetStr = arguments[1].GetStrValue(exm);
1337:                         return (exm.VEvaluator.GetMatch(p, targetStr, start, end));
1338:                     }
1339:                 }
1340:                 else
1341:                 {
1342:                     Int64 charaNum = exm.VEvaluator.CHARANUM;
1343:                     if (start >= charaNum || start < 0 || end > charaNum || end < 0)
1344:                         throw new CodeEE("CMATCH関数の範囲指定がキャラクタ配列の範囲を超えています(" + start.ToString() + "～" + end.ToString() + ")");
1345:                     if (arguments[0].GetOperandType() == typeof(Int64))
1346:                     {
1347:                         Int64 targetValue = arguments[1].GetIntValue(exm);
1348:                         return (exm.VEvaluator.GetMatchChara(p, targetValue, start, end));
1349:                     }
1350:                     else
1351:                     {
1352:                         string targetStr = arguments[1].GetStrValue(exm);
1353:                         return (exm.VEvaluator.GetMatchChara(p, targetStr, start, end));
1354:                     }
1355:                 }
1356:             }
1357: 
1358:             public override bool UniqueRestructure(ExpressionMediator exm, IOperandTerm[] arguments)
1359:             {
1360:                 arguments[0].Restructure(exm);
1361:                 for (int i = 1; i < arguments.Length; i++)
1362:                 {
1363:                     if (arguments[i] == null)
1364:                         continue;
1365:                     arguments[i] = arguments[i].Restructure(exm);
1366:                 }
1367:                 return false;
1368:             }
1369:         }
