221:         private sealed class FindcharaMethod : FunctionMethod
222:         {
223:             public FindcharaMethod(bool last)
224:             {
225:                 ReturnType = typeof(Int64);
226:                 argumentTypeArray = null;
227:                 CanRestructure = false;
228:                 isLast = last;
229:             }
230: 
231:             readonly bool isLast;
232:             public override string CheckArgumentType(string name, IOperandTerm[] arguments)
233:             {
234:                 //通常3つ、1つ省略可能で2～3の引数が必要。
235:                 if (arguments.Length < 2)
236:                     return name + "関数には少なくとも2つの引数が必要です";
237:                 if (arguments.Length > 4)
238:                     return name + "関数の引数が多すぎます";
239: 
240:                 if (arguments[0] == null)
241:                     return name + "関数の1番目の引数は省略できません";
242:                 if (!(arguments[0] is VariableTerm))
243:                     return name + "関数の1番目の引数の型が正しくありません";
244:                 if (!(((VariableTerm)arguments[0]).Identifier.IsCharacterData))
245:                     return name + "関数の1番目の引数の変数がキャラクタ変数ではありません";
246:                 if (arguments[1] == null)
247:                     return name + "関数の2番目の引数は省略できません";
248:                 if (arguments[1].GetOperandType() != arguments[0].GetOperandType())
249:                     return name + "関数の2番目の引数の型が正しくありません";
250:                 //3番目は省略可能
251:                 if ((arguments.Length >= 3) && (arguments[2] != null) && (arguments[2].GetOperandType() != typeof(Int64)))
252:                     return name + "関数の3番目の引数の型が正しくありません";
253:                 //4番目は省略可能
254:                 if ((arguments.Length >= 4) && (arguments[3] != null) && (arguments[3].GetOperandType() != typeof(Int64)))
255:                     return name + "関数の4番目の引数の型が正しくありません";
256:                 return null;
257:             }
258:             public override Int64 GetIntValue(ExpressionMediator exm, IOperandTerm[] arguments)
259:             {
260:                 VariableTerm vTerm = (VariableTerm)arguments[0];
261:                 VariableToken varID = vTerm.Identifier;
262: 
263:                 Int64 elem = 0;
264:                 if (vTerm.Identifier.IsArray1D)
265:                     elem = vTerm.GetElementInt(1, exm);
266:                 else if (vTerm.Identifier.IsArray2D)
267:                 {
268:                     elem = vTerm.GetElementInt(1, exm) << 32;
269:                     elem += vTerm.GetElementInt(2, exm);
270:                 }
271:                 Int64 startindex = 0;
272:                 Int64 lastindex = exm.VEvaluator.CHARANUM;
273:                 if (arguments.Length >= 3 && arguments[2] != null)
274:                     startindex = arguments[2].GetIntValue(exm);
275:                 if (arguments.Length >= 4 && arguments[3] != null)
276:                     lastindex = arguments[3].GetIntValue(exm);
277:                 if (startindex < 0 || startindex >= exm.VEvaluator.CHARANUM)
278:                     throw new CodeEE((isLast ? "" : "") + "関数の第3引数(" + startindex.ToString() + ")はキャラクタ位置の範囲外です");
279:                 if (lastindex < 0 || lastindex > exm.VEvaluator.CHARANUM)
280:                     throw new CodeEE((isLast ? "" : "") + "関数の第4引数(" + lastindex.ToString() + ")はキャラクタ位置の範囲外です");
281:                 long ret;
282:                 if (varID.IsString)
283:                 {
284:                     string word = arguments[1].GetStrValue(exm);
285:                     ret = exm.VEvaluator.FindChara(varID, elem, word, startindex, lastindex, isLast);
286:                 }
287:                 else
288:                 {
289:                     Int64 word = arguments[1].GetIntValue(exm);
290:                     ret = exm.VEvaluator.FindChara(varID, elem, word, startindex, lastindex, isLast);
291:                 }
292:                 return (ret);
293:             }
294:         }
