1761:         private sealed class FindElementMethod : FunctionMethod
1762:         {
1763:             public FindElementMethod(bool last)
1764:             {
1765:                 ReturnType = typeof(Int64);
1766:                 argumentTypeArray = null;
1767:                 CanRestructure = true; //すべて定数項ならできるはず
1768:                 HasUniqueRestructure = true;
1769:                 isLast = last;
1770:                 funcName = isLast ? "FINDLASTELEMENT" : "FINDELEMENT";
1771:             }
1772: 
1773:             readonly bool isLast;
1774:             readonly string funcName;
1775:             public override string CheckArgumentType(string name, IOperandTerm[] arguments)
1776:             {
1777:                 if (arguments.Length < 2)
1778:                     return name + "関数には少なくとも2つの引数が必要です";
1779:                 if (arguments.Length > 5)
1780:                     return name + "関数の引数が多すぎます";
1781:                 if (arguments[0] == null)
1782:                     return name + "関数の1番目の引数は省略できません";
1783:                 if (!(arguments[0] is VariableTerm varToken))
1784:                     return name + "関数の1番目の引数が変数ではありません";
1785:                 if (varToken.Identifier.IsArray2D || varToken.Identifier.IsArray3D)
1786:                     return name + "関数は二重配列・三重配列には対応していません";
1787:                 if (!varToken.Identifier.IsArray1D)
1788:                     return name + "関数の1番目の引数が配列変数ではありません";
1789:                 Type baseType = arguments[0].GetOperandType();
1790:                 if (arguments[1] == null)
1791:                     return name + "関数の2番目の引数は省略できません";
1792:                 if (arguments[1].GetOperandType() != baseType)
1793:                     return name + "関数の2番目の引数の型が正しくありません";
1794:                 if ((arguments.Length >= 3) && (arguments[2] != null) && (arguments[2].GetOperandType() != typeof(Int64)))
1795:                     return name + "関数の3番目の引数の型が正しくありません";
1796:                 if ((arguments.Length >= 4) && (arguments[3] != null) && (arguments[3].GetOperandType() != typeof(Int64)))
1797:                     return name + "関数の4番目の引数の型が正しくありません";
1798:                 if ((arguments.Length >= 5) && (arguments[4] != null) && (arguments[4].GetOperandType() != typeof(Int64)))
1799:                     return name + "関数の5番目の引数の型が正しくありません";
1800:                 return null;
1801:             }
1802: 
1803:             public override Int64 GetIntValue(ExpressionMediator exm, IOperandTerm[] arguments)
1804:             {
1805:                 bool isExact = false;
1806:                 VariableTerm varTerm = (VariableTerm)arguments[0];
1807: 
1808:                 Int64 start = (arguments.Length > 2 && arguments[2] != null) ? arguments[2].GetIntValue(exm) : 0;
1809:                 Int64 end = (arguments.Length > 3 && arguments[3] != null) ? arguments[3].GetIntValue(exm) : varTerm.GetLength();
1810:                 if (arguments.Length > 4 && arguments[4] != null)
1811:                     isExact = (arguments[4].GetIntValue(exm) != 0);
1812: 
1813:                 FixedVariableTerm p = varTerm.GetFixedVariableTerm(exm);
1814:                 p.IsArrayRangeValid(start, end, funcName, 3L, 4L);
1815: 
1816:                 if (arguments[0].GetOperandType() == typeof(Int64))
1817:                 {
1818:                     Int64 targetValue = arguments[1].GetIntValue(exm);
1819:                     return exm.VEvaluator.FindElement(p, targetValue, start, end, isExact, isLast);
1820:                 }
1821:                 else
1822:                 {
1823:                     Regex targetString;
1824:                     try
1825:                     {
1826:                         targetString = new Regex(arguments[1].GetStrValue(exm));
1827:                     }
1828:                     catch (ArgumentException)
1829:                     {
1830:                         throw new CodeEE("第2引数が正規表現として不正です");
1831:                     }
1832:                     return exm.VEvaluator.FindElement(p, targetString, start, end, isExact, isLast);
1833:                 }
1834:             }
1835:             
1836:             
1837:             public override bool UniqueRestructure(ExpressionMediator exm, IOperandTerm[] arguments)
1838:             {
1839:                 arguments[0].Restructure(exm);
1840:                 VariableTerm varToken = arguments[0] as VariableTerm;
1841:                 bool isConst = varToken.Identifier.IsConst;
1842:                 for (int i = 1; i < arguments.Length; i++)
1843:                 {
1844:                     if (arguments[i] == null)
1845:                         continue;
1846:                     arguments[i] = arguments[i].Restructure(exm);
1847:                     if (isConst && !(arguments[i] is SingleTerm))
1848:                         isConst = false;
1849:                 }
1850:                 return isConst;
1851:             }
1852:         }
