4069: 					case "GETKEYTRIGGERED": return (s < 0) && (toggle != keytoggle[keycode]) ? 1 : 0;//初回はtrue、2回目以降はトグル状態が前回と違う場合のみ1
4070: 				}
4071: 				throw new ExeEE("異常な分岐");
4072: 			}
