2554:             {
2555:                 string baseStr = arguments[0].GetStrValue(exm);
2556: 
2557:                 //全角文字があるなら数値ではない
2558:                 if (baseStr.Length < LangManager.GetStrlenLang(baseStr))
2559:                     return (0);
2560:                 StringStream st = new StringStream(baseStr);
2561:                 if (!char.IsDigit(st.Current) && st.Current != '+' && st.Current != '-')
2562:                     return (0);
2563:                 else if ((st.Current == '+' || st.Current == '-') && !char.IsDigit(st.Next))
2564:                     return (0);
2565:                 if (!LexicalAnalyzer.NumericCheck(st))
2566:                     return (0);
2567:                 if (!st.EOS)
2568:                 {
2569:                     if (st.Current == '.')
2570:                     {
2571:                         st.ShiftNext();
2572:                         while (!st.EOS)
2573:                         {
2574:                             if (!char.IsDigit(st.Current))
2575:                                 return (0);
2576:                             st.ShiftNext();
2577:                         }
2578:                     }
2579:                     else
2580:                         return (0);
2581:                 }
2582:                 return 1;
2583:             }
2584:         }
