3433: 					return string.Format(Properties.Resources.SyntaxErrMesMethodDefaultArgumentType0, name, 1 + 1);
3434: 				if (arguments.Length == 2)
3435: 					return null;
3436: 				if (arguments.Length != 6)
3437: 					return string.Format(Properties.Resources.SyntaxErrMesMethodDefaultArgumentNum0, name);
3438: 				for (int i = 2; i < arguments.Length; i++)
3439: 				{
3440: 					if (arguments[i] == null)
