2748:                     return name + "関数の1番目の引数が配列変数ではありません";
2749:                 if (arguments.Length == 1)
2750:                     return null;
2751:                 if ((arguments[1] != null) && (arguments[1].GetOperandType() != typeof(string)))
2752:                     return name + "関数の2番目の変数が文字列ではありません";
2753:                 if (arguments.Length == 2)
2754:                     return null;
