2767:                 Int64 index1 = (arguments.Length >= 3 && arguments[2] != null) ? arguments[2].GetIntValue(exm) : 0;
2768:                 Int64 index2 = (arguments.Length == 4 && arguments[3] != null) ? arguments[3].GetIntValue(exm) : varTerm.GetLastLength() - index1;
2769: 
2770:                 FixedVariableTerm p = varTerm.GetFixedVariableTerm(exm);
2771: 
2772:                 if (index2 < 0)
2773:                     throw new CodeEE("STRJOINの第4引数(" + index2.ToString()+ ")が負の値になっています");
2774: 
2775:                 p.IsArrayRangeValid(index1, index1 + index2, "STRJOIN", 2L, 3L);
