2349:         private sealed class ToIntMethod : FunctionMethod
2350:         {
2351:             public ToIntMethod()
2352:             {
2353:                 ReturnType = typeof(Int64);
2354:                 argumentTypeArray = new Type[] { typeof(string) };
2355:                 CanRestructure = true;
2356:             }
2357: 
2358:             public override Int64 GetIntValue(ExpressionMediator exm, IOperandTerm[] arguments)
2359:             {
2360:                 string str = arguments[0].GetStrValue(exm);
2361:                 if (str == null || str == "")
2362:                     return (0);
2363:                 //全角文字が入ってるなら無条件で0を返す
2364:                 if (str.Length < LangManager.GetStrlenLang(str))
2365:                     return (0);
2366:                 StringStream st = new StringStream(str);
2367:                 if (!char.IsDigit(st.Current) && st.Current != '+' && st.Current != '-')
2368:                     return (0);
2369:                 else if ((st.Current == '+' || st.Current == '-') && !char.IsDigit(st.Next))
2370:                     return (0);
2371:                 Int64 ret = LexicalAnalyzer.ReadInt64(st, true);
2372:                 if (!st.EOS)
2373:                 {
2374:                     if (st.Current == '.')
2375:                     {
2376:                         st.ShiftNext();
2377:                         while (!st.EOS)
2378:                         {
2379:                             if (!char.IsDigit(st.Current))
